package com.portfoliopro.controller;
import com.portfoliopro.dto.StockRequest; import com.portfoliopro.entity.*; import com.portfoliopro.repository.*; import com.portfoliopro.service.StockService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") public class AdminController {private final StockService stocks;private final UserRepository users;private final TradeRepository trades;private final TransactionRepository transactions;public AdminController(StockService stocks,UserRepository users,TradeRepository trades,TransactionRepository transactions){this.stocks=stocks;this.users=users;this.trades=trades;this.transactions=transactions;}@GetMapping("/users") public List<User> users(){return users.findAll();}@GetMapping("/trades") public List<Trade> trades(){return trades.findAll();}@GetMapping("/transactions") public List<Transaction> transactions(){return transactions.findAll();}@PostMapping("/stocks") public Stock create(@Valid @RequestBody StockRequest r){return stocks.save(r);}@PutMapping("/stocks/{id}") public Stock update(@PathVariable Long id,@Valid @RequestBody StockRequest r){return stocks.update(id,r);}@DeleteMapping("/stocks/{id}") public void delete(@PathVariable Long id){stocks.delete(id);}}
